from donnees import C,E

CHAPITRES=[]
CHAPITRES.append(C(1,'Masse, volume et masse volumique','Comment reconnaître un matériau sans le découper ?',
['Mesurer une masse et un volume avec les unités adaptées.','Construire puis exploiter la relation entre masse et volume.','Identifier les limites d’une comparaison expérimentale.'],
['Lire une graduation et utiliser la proportionnalité.'],[
('Mesurer deux grandeurs différentes',r'La masse $m$ mesure une quantité de matière au sens usuel du collège ; on la mesure avec une balance. Le volume $V$ est l’espace occupé. Pour un liquide, placer l’œil à hauteur du bas du ménisque d’une éprouvette graduée. Tarer la balance avec le récipient vide permet de mesurer directement la masse du liquide. On note toujours valeur et unité.','c01-mesure','Un objet immergé déplace un volume d’eau égal à son volume, s’il est totalement immergé et ne se dissout pas.'),
('Passer d’une unité à une autre',r'$1\unite{L}=1\unite{dm^3}$, $1\unite{mL}=1\unite{cm^3}$ et $1\unite{m^3}=1\,000\unite{L}$. Les conversions cubiques demandent de la vigilance : $1\unite{m^3}=1\,000\,000\unite{cm^3}$. Pour un solide compact insoluble, la différence entre les volumes final et initial de l’eau donne le volume déplacé. Une bulle collée au solide fausse ce résultat.','',''),
('Une propriété du matériau',r'Pour une substance homogène, à température et pression fixées, masse et volume sont proportionnels. Le quotient $\rho=m/V$, appelé masse volumique, caractérise la substance dans ces conditions. On utilise aussi $m=\rho V$ et $V=m/\rho$. Avec $m$ en g et $V$ en mL, $\rho$ s’exprime en g/mL. $1\unite{g/mL}=1\,000\unite{kg/m^3}$.','c01-rho','Les pentes des droites diffèrent : un même volume de deux substances peut avoir des masses différentes.'),
('Comparer avec prudence',r'À environ $20\,^{\circ}\mathrm C$, on prend ici $\rho_{\text{eau}}\approx1{,}00\unite{g/mL}$, $\rho_{\text{aluminium}}\approx2{,}70\unite{g/cm^3}$ et $\rho_{\text{fer}}\approx7{,}9\unite{g/cm^3}$. Une valeur proche aide à identifier un matériau, sans suffire à prouver sa composition. La température, une cavité ou un mélange peuvent modifier la mesure. Chauffer un liquide le dilate généralement : sa masse volumique diminue si sa masse reste constante.','','')],
r'Un solide a une masse de $54{,}0\unite g$. L’éprouvette passe de $30{,}0$ à $50{,}0\unite{mL}$. Son volume vaut $50{,}0-30{,}0=20{,}0\unite{cm^3}$ ; donc $\rho=54{,}0/20{,}0=2{,}70\unite{g/cm^3}$. La valeur est compatible avec de l’aluminium compact. On vérifie l’immersion et l’absence de bulles avant de conclure.',
r'\textbf{Question.} Un liquide inconnu est-il compatible avec de l’eau ? En classe, peser un récipient sec, puis y verser successivement trois volumes connus du même liquide, sans changer la température. Mesurer chaque masse par différence. Construire $m$ en fonction de $V$, avec des axes gradués et des unités. Comparer les quotients et leur dispersion. Proposer une explication si un point s’écarte. Ne pas goûter. \textbf{À rendre :} tableau, graphique, calcul et conclusion limitée à la précision des instruments.',
[r'La masse se mesure avec une balance ; le volume avec une méthode adaptée.',r'$V_{\text{solide}}=V_f-V_i$ pour une immersion convenable.',r'$\rho=m/V$ avec des unités cohérentes.',r'À conditions fixées, doubler le volume d’une substance double sa masse.',r'Une identification exige une comparaison et une discussion des limites.'],
r'« Le plus lourd est le plus dense. » Une grande bouteille d’huile peut être plus lourde qu’un petit verre d’eau tout en ayant une masse volumique plus faible.',[
E('Choisir l’instrument','Quel appareil mesure la masse d’un caillou ?@@Quelle grandeur exprime une indication en mL ?','Une balance, après réglage du zéro ou tare du récipient.@@Il s’agit d’un volume, et non d’une masse.'),
E('Convertir sans confondre',r'Convertir $0{,}250\unite L$ en mL.@@Convertir $35\unite{cm^3}$ en mL.',r'$0{,}250\times1\,000=250\unite{mL}$.@@$35\unite{cm^3}=35\unite{mL}$.',calculs=[('0.250*1000',250)]),
E('Lire une immersion',r'L’eau passe de $42$ à $57\unite{mL}$. Quel est le volume du solide ?@@Nommer une condition nécessaire.',r'$V=57-42=15\unite{mL}=15\unite{cm^3}$.@@Le solide doit être entièrement immergé, insoluble et sans bulle adhérente.',calculs=[('57-42',15)]),
E('Une tare utile',r'Le récipient vide pèse $82\unite g$ ; rempli, $132\unite g$. Calculer la masse du liquide.@@Que ferait la touche tare avant le remplissage ?',r'$m=132-82=50\unite g$.@@Elle remettrait l’affichage à zéro avec le récipient vide ; la masse du liquide serait ensuite affichée directement.',calculs=[('132-82',50)]),
E('Calcul direct',r'$40\unite{mL}$ d’un liquide ont une masse de $32\unite g$. Calculer sa masse volumique.@@Est-elle supérieure à celle de l’eau ?',r'$\rho=32/40=0{,}80\unite{g/mL}$.@@Non : $0{,}80<1{,}00$ dans les conditions indiquées.',calculs=[('32/40',.8)]),
E('Une masse à prévoir',r'Un matériau a $\rho=2{,}7\unite{g/cm^3}$. Quelle masse pour $30\unite{cm^3}$ ?@@Quelle masse pour un volume double ?',r'$m=\rho V=2{,}7\times30=81\unite g$.@@À conditions identiques, $162\unite g$ : la masse est proportionnelle au volume.',calculs=[('2.7*30',81),('2*81',162)]),
E('Trouver le volume',r'Un objet compact de $79\unite g$ a $\rho=7{,}9\unite{g/cm^3}$. Trouver $V$.@@Exprimer ce résultat en mL.',r'$V=m/\rho=79/7{,}9=10\unite{cm^3}$.@@Cela correspond à $10\unite{mL}$.',calculs=[('79/7.9',10)]),
E('Reconnaître une proportionnalité',r'Pour les volumes $10$, $20$ et $30\unite{mL}$, on mesure $9$, $18$ et $27\unite g$. Le modèle proportionnel convient-il ?@@Quelle valeur de $\rho$ en déduire ?',r'Oui : les trois quotients masse/volume valent $0{,}90$.@@$\rho=0{,}90\unite{g/mL}$ ; le graphe est une droite passant par l’origine.',calculs=[('9/10',.9),('18/20',.9),('27/30',.9)]),
E('Comparer à volume égal',r'Deux blocs de même volume $12\unite{cm^3}$ sont en aluminium et en fer. Calculer leurs masses avec les données du cours.@@Lequel a la plus grande masse volumique ?',r'Aluminium : $2{,}70\times12=32{,}4\unite g$ ; fer : $7{,}9\times12=94{,}8\unite g$.@@Le fer ; ici la comparaison des masses est pertinente parce que les volumes sont égaux.',calculs=[('2.7*12',32.4),('7.9*12',94.8)]),
E('Changement d’unité',r'Exprimer $0{,}85\unite{g/mL}$ en kg/m$^3$.@@Quelle masse ont $2\unite L$ de ce liquide ?',r'$0{,}85\unite{g/mL}=850\unite{kg/m^3}$.@@$2\unite L=2\,000\unite{mL}$ ; $m=0{,}85\times2\,000=1\,700\unite g=1{,}7\unite{kg}$.',calculs=[('.85*1000',850),('.85*2000',1700)]),
E('Une bulle gênante',r'Une bulle adhère au solide immergé. Le volume mesuré est-il trop grand ou trop petit ?@@Quel effet cela a-t-il sur $m/V$ ?',r'Il est trop grand : le déplacement inclut le volume de la bulle.@@À masse inchangée, diviser par un volume trop grand donne une masse volumique trop faible.'),
E('Un objet creux',r'Une pièce de $27\unite g$ occupe extérieurement $20\unite{cm^3}$. Calculer sa masse volumique moyenne.@@Cette valeur suffit-elle à exclure une coque en aluminium ?',r'$27/20=1{,}35\unite{g/cm^3}$.@@Non : un objet creux peut avoir une masse volumique moyenne inférieure à celle du matériau de sa coque. Il faut examiner la présence d’une cavité.',calculs=[('27/20',1.35)]),
E('Diagnostiquer un graphique',r'Un élève pèse le récipient avec chaque quantité de liquide sans soustraire sa masse. La droite passe-t-elle par l’origine ?@@Comment corriger les données ?',r'Non en général : à volume nul, le récipient a encore une masse non nulle.@@Soustraire la masse du récipient à toutes les masses, ou refaire les mesures après tare.'),
E('Comparer deux protocoles',r'Une éprouvette est graduée tous les $2\unite{mL}$. On peut immerger une bille ou dix billes identiques à la fois. Quel protocole réduit l’effet relatif de la lecture ?@@On trouve $40\unite{mL}$ pour dix billes. Calculer le volume moyen.',r'Dix billes donnent un déplacement plus grand ; une même difficulté de lecture représente alors une plus petite part du volume total.@@$40/10=4{,}0\unite{mL}$ par bille. Vérifier qu’aucune bulle n’est emprisonnée.',calculs=[('40/10',4)]),
E('Un liquide qui se dilate',r'La masse reste $200\unite g$ ; le volume passe de $200$ à $204\unite{mL}$. Calculer les deux masses volumiques.@@Expliquer le sens de la variation.',r'Avant : $200/200=1{,}00\unite{g/mL}$ ; après : $200/204\approx0{,}980\unite{g/mL}$.@@La même masse occupe plus de volume : la masse volumique diminue. La matière n’a pas disparu.',calculs=[('200/204',200/204)])],
E('La pièce mystérieuse',r'Une pièce pèse $43{,}2\unite g$ et déplace $16{,}0\unite{mL}$. Calculer $\rho$.@@Une référence donne $2{,}70\unite{g/cm^3}$ pour l’aluminium. Formuler une conclusion.@@Proposer deux contrôles avant d’identifier le matériau.',r'$\rho=43{,}2/16{,}0=2{,}70\unite{g/cm^3}$.@@La mesure est compatible avec de l’aluminium compact dans les conditions de la référence ; elle ne constitue pas une preuve unique.@@Recommencer la mesure après retrait des bulles et vérifier l’absence de cavité. On peut aussi améliorer la lecture du volume.',calculs=[('43.2/16',2.7)])))

CHAPITRES.append(C(2,'L’air, les gaz et la pression','Pourquoi une seringue bouchée résiste-t-elle ?',
['Décrire l’air comme un mélange de gaz.','Interpréter compression et détente avec un modèle particulaire.','Distinguer pression, masse et volume.'],['Corps pur, mélange et volume.'],[
('De quoi l’air est-il fait ?',r'L’air sec contient environ $78\,\%$ de diazote, $21\,\%$ de dioxygène et $1\,\%$ d’autres gaz en volume. L’air réel contient aussi une quantité variable de vapeur d’eau. Ces constituants sont mélangés ; ils ne forment pas des couches séparées dans une seringue. Le dioxygène permet de nombreuses combustions, mais l’air n’est pas du dioxygène pur.','c02-air','Pour 100 parts d’air sec : proportions arrondies des principaux constituants.'),
('Un gaz occupe un volume',r'Un gaz occupe tout l’espace disponible d’un récipient. Dans une seringue fermée, enfoncer doucement le piston réduit le volume sans retirer de gaz : c’est une compression. Dans le modèle, les molécules restent présentes et plus rapprochées ; elles ne deviennent pas plus petites. Lors d’une détente, l’espace disponible augmente.','',''),
('La pression et ses unités',r'Les particules d’un gaz exercent des actions sur les parois. Un capteur mesure la pression $p$, en pascals (Pa). On utilise aussi l’hectopascal : $1\unite{hPa}=100\unite{Pa}$, et le bar : $1\unite{bar}=100\,000\unite{Pa}$. À quantité de gaz et température constantes, une compression augmente la pression. On ne suppose pas cette température constante pour une compression brusque.','c02-pression','Même quantité de gaz, volume plus faible : le modèle représente des particules plus rapprochées.'),
('L’air possède une masse',r'Peser un ballon avant puis après retrait d’une partie de son air montre une différence de masse, si l’on maîtrise les conditions de mesure. À environ $20\,^{\circ}\mathrm C$ et à pression voisine de la pression atmosphérique, on retient comme ordre de grandeur $1{,}2\unite g$ par litre d’air. Cette valeur dépend fortement de la température et de la pression. Une indication en litres ne donne donc pas directement une masse universelle.','','')],
r'Un échantillon de $500\unite{mL}$ d’air sec correspond approximativement à $0{,}21\times500=105\unite{mL}$ de dioxygène et $0{,}78\times500=390\unite{mL}$ de diazote, aux mêmes température et pression. Les $5\unite{mL}$ restants représentent les autres gaz. Les proportions restent inchangées lors d’un simple prélèvement homogène.',
r'\textbf{Question.} Comment varie la pression quand le volume diminue ? Utiliser une seringue et un capteur scolaires, sans aiguille. Fermer le dispositif et attendre l’équilibre thermique. Relever la pression pour trois volumes autorisés par le professeur, sans forcer. Revenir doucement au volume initial pour tester la reproductibilité. \textbf{À discuter :} quantité de gaz, température, étanchéité et différence entre observation qualitative et relation mathématique. Ne pas essayer de provoquer l’éjection du bouchon.',
['L’air sec est un mélange dont le diazote et le dioxygène sont les constituants principaux.','Une compression diminue le volume disponible.','La masse d’un gaz enfermé se conserve si le système est étanche.','La pression se mesure avec un capteur et s’exprime en Pa.','Les propriétés d’un gaz dépendent des conditions de température et de pression.'],
r'Une molécule ne « gonfle » pas pendant une détente : c’est principalement l’écartement entre les molécules qui change dans le modèle du gaz.',[
E('Les deux principaux gaz','Nommer les deux principaux gaz de l’air sec.@@Donner leurs proportions arrondies.','Le diazote et le dioxygène.@@Environ 78 % et 21 % en volume ; les autres gaz représentent environ 1 %.'),
E('Air ou dioxygène ?','L’air est-il un corps pur ?@@Le dioxygène est-il synonyme d’air ?','Non : il contient plusieurs espèces chimiques.@@Non : le dioxygène est un de ses constituants.'),
E('Compresser',r'Le volume d’une seringue fermée passe de $60$ à $40\unite{mL}$. Comment nommer l’opération ?@@Des molécules ont-elles été retirées ?','C’est une compression.@@Non si la seringue reste étanche : les molécules sont plus rapprochées.'),
E('Des unités de pression',r'Convertir $1\,020\unite{hPa}$ en Pa.@@Convertir $2\unite{bar}$ en Pa.',r'$1\,020\times100=102\,000\unite{Pa}$.@@$2\times100\,000=200\,000\unite{Pa}$.',calculs=[('1020*100',102000),('2*100000',200000)]),
E('Dans cent millilitres',r'Quel volume correspond approximativement au dioxygène dans $100\unite{mL}$ d’air sec ?@@Quel volume correspond aux autres gaz ?',r'$21\unite{mL}$.@@Environ $1\unite{mL}$, avec les arrondis du modèle.'),
E('Un prélèvement plus grand',r'Dans $2\unite L$ d’air sec, calculer le volume correspondant au dioxygène.@@Exprimer celui du diazote en litres.',r'$0{,}21\times2=0{,}42\unite L=420\unite{mL}$.@@$0{,}78\times2=1{,}56\unite L$.',calculs=[('.21*2',.42),('.78*2',1.56)]),
E('Lire un capteur',r'Une mesure passe de $1{,}0$ à $1{,}4\unite{bar}$ pendant une compression lente. La pression augmente-t-elle ?@@La masse augmente-t-elle forcément ?',r'Oui, de $0{,}4\unite{bar}$.@@Non : si le gaz est enfermé, sa masse reste constante. Pression et masse sont des grandeurs différentes.'),
E('Une masse d’air',r'On prend $1{,}2\unite{g/L}$ pour l’air dans les conditions du cours. Estimer la masse de $5\unite L$.@@Nommer deux conditions à préciser.',r'$m=1{,}2\times5=6{,}0\unite g$.@@La température et la pression ; la valeur donnée ne convient pas à toutes les conditions.',calculs=[('1.2*5',6)]),
E('Peser par différence',r'Un ballon équipé de sa valve passe de $425{,}6$ à $423{,}2\unite g$ après retrait d’air. Quelle masse a été retirée ?@@Estimer son volume avec $1{,}2\unite{g/L}$.',r'$425{,}6-423{,}2=2{,}4\unite g$.@@$V=2{,}4/1{,}2=2{,}0\unite L$, si les conditions justifient cette masse volumique.',calculs=[('425.6-423.2',2.4),('2.4/1.2',2)]),
E('Modéliser une détente','On passe de 20 à 40 mL sans fuite. Comment modifier un dessin de particules ?@@Que doit-on conserver dans le dessin ?','Agrandir l’espace du récipient et répartir davantage les particules.@@Le même nombre et les mêmes types de particules : aucun constituant n’est créé.'),
E('Une conclusion excessive','Après une seule compression, un élève affirme que doubler la pression divise toujours le volume par deux. Cette mesure suffit-elle ?@@Quel paramètre faudrait-il notamment contrôler ?','Non. Une seule observation qualitative ne prouve pas une loi valable dans toutes les situations.@@La température, mais aussi la quantité de gaz et l’étanchéité. Le cours n’impose ici qu’une évolution qualitative.'),
E('L’air humide','Pourquoi la composition de l’air sec ne décrit-elle pas exactement toute atmosphère humide ?@@Peut-on additionner 78 %, 21 % et une forte part de vapeur d’eau sans réajuster ?','Parce que de la vapeur d’eau s’ajoute au mélange et modifie les fractions de l’ensemble.@@Non : les proportions de toutes les espèces doivent totaliser 100 %. Les 78 % et 21 % se rapportent à l’air sec.'),
E('Chercher une fuite','Le piston reste fixe, mais la pression d’un gaz comprimé baisse lentement. Proposer deux explications.@@Comment les départager ?','Une fuite peut réduire la quantité de gaz ; le gaz peut aussi se refroidir après une compression rapide.@@Attendre l’équilibre thermique, contrôler les raccords et répéter l’essai. Une baisse seule ne permet pas de choisir.'),
E('Doubler l’échantillon',r'On dispose de $250\unite{mL}$ puis de $500\unite{mL}$ d’air sec dans les mêmes conditions. Calculer le dioxygène correspondant.@@La proportion a-t-elle doublé ?',r'$52{,}5\unite{mL}$ puis $105\unite{mL}$.@@Non : les deux quantités ont doublé, mais le pourcentage reste $21\,\%$.',calculs=[('.21*250',52.5),('.21*500',105)]),
E('Un modèle incomplet','Un dessin représente l’air par des points identiques immobiles, tous au fond d’une boîte. Identifier deux limites.@@Proposer un dessin mieux légendé.','L’air est un mélange et un gaz occupe tout le volume ; ses particules sont en mouvement.@@Utiliser plusieurs codes pour les espèces, répartis dans toute la boîte. Signaler que positions et tailles sont schématiques.')],
E('Dimensionner un modèle',r'On veut représenter $1\unite L$ d’air sec par 200 jetons. Combien de jetons de chaque catégorie prévoir ?@@Quel volume réel chaque jeton code-t-il dans ce modèle ?@@Donner deux limites de la représentation.',r'$156$ pour le diazote, $42$ pour le dioxygène et $2$ pour les autres gaz.@@$1\,000/200=5\unite{mL}$ par jeton, en proportion de volume et dans les mêmes conditions.@@Le modèle ne montre ni les distances réelles ni les mouvements. Un jeton ne correspond pas à une molécule réelle de cinq millilitres.',calculs=[('.78*200',156),('.21*200',42),('1000/200',5)])))

CHAPITRES.append(C(3,'États et changements d’état : le modèle','Que devient l’eau quand elle se vaporise ?',
['Interpréter les états physiques avec des particules.','Lire une courbe de chauffage et reconnaître un palier.','Expliquer conservation de la masse et variation du volume.'],['États solide, liquide, gazeux ; température.'],[
('Un modèle pour expliquer',r'Dans un solide, les particules sont proches et leur position reste organisée ou liée autour de positions moyennes ; elles vibrent. Dans un liquide, elles sont proches mais peuvent se déplacer les unes par rapport aux autres. Dans un gaz, elles sont beaucoup plus espacées et mobiles. Le modèle explique forme et volume sans représenter fidèlement la taille des particules.','c03-etats','Les dessins gardent les mêmes particules ; leur disposition change selon l’état.'),
('Nommer les transformations',r'Fusion : solide vers liquide ; solidification : liquide vers solide. Vaporisation : liquide vers gaz ; liquéfaction : gaz vers liquide. La vaporisation peut se produire à la surface, par évaporation, sans ébullition. La sublimation et la condensation solide relient directement solide et gaz. Une buée est composée de fines gouttelettes liquides ; la vapeur d’eau gazeuse est invisible.','',''),
('Lire une courbe expérimentale',r'À pression constante, le changement d’état d’un corps pur se produit à température constante tant que les deux états coexistent : un palier apparaît dans le modèle idéal. Pour l’eau pure sous une pression voisine de $1{,}013\unite{bar}$, fusion à $0\,^{\circ}\mathrm C$ et ébullition vers $100\,^{\circ}\mathrm C$. Une pression différente ou des substances dissoutes modifient ces repères.','c03-courbe','Pendant le palier, l’énergie transférée contribue au changement d’état ; la température ne suffit pas à décrire le phénomène.'),
('Ce qui se conserve',r'Lors d’un changement d’état sans fuite, la masse se conserve : les molécules ne sont ni détruites ni créées. Le volume peut changer, car leur organisation et leur écartement changent. La glace occupe plus de volume que la même masse d’eau liquide, particularité importante pour les canalisations et les milieux naturels. La dilatation de l’eau liquide et la fonte des glaces continentales contribuent à l’élévation du niveau marin.','','')],
r'Un flacon fermé contient $50\unite g$ d’eau, puis cette eau gèle entièrement. La masse d’eau reste $50\unite g$ ; son volume augmente. Si l’on observe seulement $48\unite g$ après chauffage dans un récipient ouvert, cela ne réfute pas la conservation : une partie de l’eau a pu quitter le récipient à l’état gazeux.',
r'\textbf{Question.} Comment évolue la température pendant la fusion ? Le professeur fournit un mélange eau-glace et un dispositif de mesure. Relever la température à intervalles réguliers, sans mettre la sonde contre la paroi. Noter simultanément les états présents. Tracer température en fonction du temps. Distinguer un vrai palier des petites variations de mesure. \textbf{Prolongement documentaire :} comparer glace flottante et glacier continental ; justifier pourquoi leurs fontes n’ont pas le même effet direct sur le niveau de la mer.',
['Un changement d’état conserve les espèces chimiques.','Les particules du gaz sont bien plus espacées que celles du liquide.','La vapeur d’eau gazeuse est invisible ; la buée est liquide.','Les températures de changement d’état dépendent notamment de la pression.','Masse conservée ne signifie pas volume conservé.'],
r'« L’eau bout toujours à $100\,^{\circ}\mathrm C$. » Cette valeur suppose une eau pure et une pression proche de la pression atmosphérique au niveau de la mer.',[
E('Nommer un passage','Comment nommer le passage de la glace à l’eau liquide ?@@Et celui de la vapeur d’eau à l’eau liquide ?','La fusion.@@La liquéfaction ; on rencontre aussi le mot condensation liquide.'),
E('À l’échelle des particules','Dans quel état les particules sont-elles les plus éloignées ?@@Un liquide a-t-il une forme propre ?','À l’état gazeux, dans les conditions usuelles comparées.@@Non. Il épouse le récipient, mais conserve approximativement son volume.'),
E('Buée et vapeur','La buée visible sur une vitre est-elle un gaz ?@@Pourquoi voit-on un nuage au-dessus d’une casserole ?','Non : ce sont de fines gouttes d’eau liquide.@@Une partie de la vapeur se liquéfie dans l’air plus froid et forme des gouttelettes qui diffusent la lumière.'),
E('Une masse conservée',r'$80\unite g$ de glace fondent dans un récipient fermé. Quelle masse d’eau obtient-on ?@@Le volume est-il forcément le même ?',r'$80\unite g$ d’eau.@@Non : l’eau liquide occupe moins de volume que la même masse de glace.'),
E('Évaporation','Un linge sèche sans bouillir. Quel changement d’état a lieu ?@@Quelle espèce quitte le linge ?','Une vaporisation par évaporation à la surface.@@De l’eau, sous forme gazeuse ; les molécules d’eau restent des molécules d’eau.'),
E('Lire un palier',r'Une eau pure reste à $0\,^{\circ}\mathrm C$ tandis que la glace fond. Quels états coexistent ?@@De l’énergie est-elle néanmoins transférée ?','Solide et liquide.@@Oui : un transfert d’énergie peut provoquer la fusion sans hausse de température pendant le palier.'),
E('Choisir un état',r'Sous pression usuelle, de l’eau pure à $-10\,^{\circ}\mathrm C$ est-elle normalement solide ou liquide ?@@Et à $25\,^{\circ}\mathrm C$ ?','Solide, dans le modèle d’équilibre usuel.@@Liquide ; on suppose les conditions ordinaires de pression et l’absence de situation particulière.'),
E('Reconnaître les étapes',r'Une courbe monte de $20$ à $100\,^{\circ}\mathrm C$, puis présente un palier. Décrire les deux étapes.@@Que faut-il connaître pour attribuer le palier à l’eau ?','D’abord le liquide se réchauffe ; puis la vaporisation se poursuit à température presque constante.@@La nature et la pureté de l’échantillon, ainsi que la pression de l’expérience.'),
E('Un bilan de masse',r'Un récipient ouvert contient $150\unite g$ d’eau avant chauffage, puis $138\unite g$. Quelle masse a quitté le récipient ?@@S’agit-il nécessairement d’une transformation chimique ?',r'$150-138=12\unite g$.@@Non : une vaporisation suffit à l’expliquer. Il faut considérer l’eau passée dans l’air pour le bilan complet.',calculs=[('150-138',12)]),
E('Comparer deux courbes','L’échantillon A présente un palier net ; B change d’état sur une plage de températures. Lequel est le plus compatible avec un corps pur à pression constante ?@@Cette seule observation prouve-t-elle toute sa composition ?','A est le plus compatible avec le modèle d’un corps pur.@@Non : la mesure a une précision limitée et d’autres informations sont nécessaires pour identifier exactement l’espèce.'),
E('Ne pas enfermer un chauffage','Pourquoi ne faut-il pas chauffer de l’eau dans un récipient hermétiquement fermé improvisé ?@@Quel lien avec le volume du gaz ?','La pression peut augmenter dangereusement ; le protocole doit être défini par le professeur avec du matériel adapté.@@La vapeur occuperait un grand volume si elle était libre. Si l’espace est imposé, la pression peut fortement croître.'),
E('La banquise et le glacier','Distinguer une glace déjà flottante d’une glace continentale.@@Pourquoi la fonte d’un glacier continental fait-elle monter le niveau de la mer ?','La première flotte déjà dans la mer ; la seconde repose sur un continent.@@L’eau du glacier s’ajoute à l’océan. Pour la glace flottante, l’effet direct est beaucoup plus faible dans le modèle simple ; elle déplaçait déjà de l’eau.'),
E('Critiquer un dessin','Un élève dessine des molécules plus grosses dans l’eau liquide chaude. Quelle modification proposer ?@@Que peut changer le chauffage ?','Conserver les molécules avec la même taille schématique.@@Leur agitation et leur espacement moyen peuvent changer ; on peut représenter cela avec des flèches et un écartement adapté.'),
E('Pression et température','Un document annonce une ébullition de l’eau pure à 90 °C en altitude. Est-ce incompatible avec le cours ?@@Quelle donnée faut-il comparer ?','Non : la température d’ébullition dépend de la pression.@@Il faut comparer les pressions, ainsi que la pureté de l’eau. La référence de 100 °C suppose une pression voisine de 1,013 bar.'),
E('Construire un argument',r'À $0\,^{\circ}\mathrm C$, deux récipients contiennent l’un de l’eau liquide et l’autre un mélange eau-glace. Peut-on les distinguer par la seule température ?@@Quelle observation ajouter ?','Non, la même température peut correspondre à des situations différentes.@@Observer la présence de glace, ou suivre l’évolution pendant un transfert d’énergie connu. La température seule ne décrit pas la proportion des états.')],
E('Le flacon qui semble perdre de la matière',r'Un montage ouvert pèse $312\unite g$ avant et $300\unite g$ après chauffage. Calculer la différence.@@Proposer une explication compatible avec la conservation de la masse.@@Comment vérifier l’explication sans fermer dangereusement le montage ?',r'$312-300=12\unite g$.@@De l’eau peut s’être vaporisée et avoir quitté la partie pesée : le bilan doit inclure cette eau.@@Le professeur peut utiliser un montage adapté pour condenser et recueillir la vapeur, puis comparer l’ensemble des masses. Ne jamais improviser un chauffage hermétique.',calculs=[('312-300',12)])))

CHAPITRES.append(C(4,'Solutions, solubilité et pH','Une eau limpide est-elle forcément pure ?',
['Distinguer dissolution, miscibilité et séparation.','Estimer une solubilité à partir de données.','Mesurer un pH et reconnaître un caractère acide ou basique.'],['Mélange homogène et unités de masse et de volume.'],[
('Une solution est un mélange',r'Le solvant dissout une ou plusieurs espèces appelées solutés. Dans une solution aqueuse, le solvant est l’eau. Dissoudre du sel ne le détruit pas : sa présence peut être mise en évidence autrement. Deux liquides sont miscibles s’ils forment un mélange homogène. Filtrer retient des particules solides assez grosses, mais ne retire pas les espèces dissoutes.','c04-dissolution','Une dissolution peut donner un mélange transparent contenant plusieurs espèces.'),
('Il existe une limite',r'À température donnée, la solubilité indique la quantité maximale de soluté que l’on peut dissoudre dans une quantité de solvant définie. On précise ici les masses solubles pour $100\unite{mL}$ d’eau. Au-delà, une partie du solide reste présente : la solution est saturée. Agiter accélère souvent la dissolution, mais ne permet pas de dépasser indéfiniment cette limite. Les gaz peuvent aussi se dissoudre dans l’eau.','',''),
('Lire une échelle de pH',r'Pour les solutions aqueuses usuelles étudiées vers $25\,^{\circ}\mathrm C$, un pH inférieur à 7 indique un caractère acide ; un pH égal à 7, la neutralité ; un pH supérieur à 7, un caractère basique. Le papier pH donne une estimation ; le pH-mètre fournit une mesure à contrôler et étalonner. Le pH est sans unité. La couleur d’une solution n’indique pas directement son pH.','c04-ph','L’échelle usuelle de 0 à 14 est un repère scolaire pour des solutions aqueuses courantes ; elle ne couvre pas toutes les situations possibles.'),
('Préserver l’eau et préparer la suite',r'Une filtration ne rend pas à elle seule une eau potable. La distillation sépare notamment l’eau de certains solutés non volatils, sans constituer une garantie universelle contre tout contaminant. Le dioxyde de carbone dissous contribue à l’acidification de l’eau ; une baisse du pH n’implique pas nécessairement de passer sous 7. \textbf{Repère pour la 3e :} les ions $\ce{H+}$ et $\ce{OH-}$ participent au caractère acide ou basique ; leur modèle sera approfondi, sans calcul ionique ici.','','')],
r'À une température donnée, on fournit une limite de $36\unite g$ de sel pour $100\unite{mL}$ d’eau. Dans $50\unite{mL}$, la masse maximale vaut $36\times50/100=18\unite g$. Si l’on ajoute $22\unite g$, il reste $22-18=4\unite g$ non dissous, après agitation suffisante. Ce calcul utilise la quantité initiale d’eau, pas le volume final de solution.',
r'\textbf{Question.} Comment estimer une limite de dissolution ? Avec les quantités et produits choisis par le professeur, ajouter de petites masses connues de sel dans un volume fixé d’eau à température stable. Agiter assez longtemps entre deux ajouts. Noter la dernière masse entièrement dissoute et la première laissant un dépôt persistant. En déduire un encadrement plutôt qu’une valeur artificiellement exacte. Sur d’autres échantillons autorisés, estimer le pH avec des bandelettes sans contaminer les flacons. Aucun mélange de produits ménagers.',
['Une solution contient un solvant et un ou plusieurs solutés.','La solubilité dépend du soluté, du solvant et de la température.','Une filtration ordinaire ne retire pas le sel dissous.','Acide, neutre et basique se distinguent par une mesure de pH.','Une eau transparente n’est pas nécessairement pure ni potable.'],
r'« pH 6 est deux fois moins acide que pH 3. » Le pH n’est pas une échelle de proportionnalité ; on ne compare pas l’acidité en divisant les nombres de pH.',[
E('Le vocabulaire','Dans une eau sucrée, nommer solvant et soluté.@@Le mélange est-il pur ?','L’eau est le solvant ; le sucre, le soluté.@@Non : il contient plusieurs espèces, même s’il est homogène et transparent.'),
E('Deux liquides','Eau et huile forment deux couches après repos. Sont-elles miscibles ?@@Comment nommer l’aspect du mélange ?','Non dans les conditions usuelles de l’expérience.@@Il est hétérogène : on distingue deux phases.'),
E('Trois pH','Classer les solutions de pH 3, 7 et 10 vers 25 °C.@@Le pH porte-t-il une unité ?','pH 3 : acide ; pH 7 : neutre ; pH 10 : basique.@@Non : le pH est un nombre sans unité.'),
E('Un filtre en papier','Peut-on retirer le sable d’une eau sableuse par filtration ?@@Retirer le sel d’une eau salée par le même filtre ?','Oui, si les grains sont retenus par le filtre.@@Non : les espèces dissoutes traversent le filtre avec l’eau.'),
E('Une solution saturée','Après agitation prolongée, un dépôt de sel persiste. Quelle limite a probablement été atteinte ?@@Pourquoi préciser la température ?','La solubilité a été atteinte : la solution est saturée, avec du solide non dissous.@@La solubilité peut varier avec la température.'),
E('Adapter une quantité',r'La limite fournie est $20\unite g$ pour $100\unite{mL}$ d’eau. Quelle masse maximale pour $250\unite{mL}$ ?@@Tout le solide se dissout-il si l’on ajoute $60\unite g$ ?',r'$20\times250/100=50\unite g$.@@Non : $10\unite g$ restent non dissous à cette température, après équilibre.',calculs=[('20*250/100',50),('60-50',10)]),
E('Conserver la masse',r'On mélange $100\unite g$ d’eau et $8\unite g$ de sel, sans perte. Quelle masse totale obtient-on ?@@Le volume total vaut-il forcément la somme des volumes initiaux ?',r'$108\unite g$.@@Non : la conservation de la masse n’impose pas l’additivité des volumes.',calculs=[('100+8',108)]),
E('Lire un encadrement',r'$14\unite g$ se dissolvent complètement ; avec $16\unite g$, un dépôt persiste dans $50\unite{mL}$ d’eau. Encadrer la masse maximale.@@Traduire pour $100\unite{mL}$ d’eau.',r'La masse maximale est au moins $14\unite g$ et inférieure à $16\unite g$.@@Elle est au moins $28\unite g$ et inférieure à $32\unite g$ pour $100\unite{mL}$, à la même température.'),
E('Le gaz d’une boisson','Pourquoi une boisson peut-elle former des bulles à l’ouverture ?@@Les bulles prouvent-elles une réaction chimique ?','Une partie du gaz dissous s’échappe lorsque les conditions changent, notamment la pression.@@Non : un dégazage peut être une transformation physique sans création d’une nouvelle espèce.'),
E('Choisir une méthode','On veut séparer l’eau et un sel dissous non volatil. Quelle méthode peut recueillir l’eau ?@@Quelle méthode peut laisser le sel comme résidu ?','Une distillation adaptée, réalisée en classe, peut recueillir l’eau après vaporisation puis liquéfaction.@@L’évaporation de l’eau peut laisser le sel. Cela ne suffit pas à identifier exactement ce résidu.'),
E('Interpréter une baisse de pH','Un échantillon passe de pH 8,2 à pH 7,8. Est-il devenu acide au sens du classement scolaire ?@@Peut-on parler d’acidification ?','Non : 7,8 reste supérieur à 7 dans les conditions indiquées.@@Oui : le pH a diminué. Acidification signifie une évolution vers un pH plus faible, pas forcément un passage sous 7.'),
E('Le résultat trop précis','Une bandelette présente une couleur intermédiaire entre pH 5 et 6. Un élève note 5,372. Critiquer.@@Quelle écriture convient mieux ?','Cette précision n’est pas justifiée par la méthode.@@Une estimation entre 5 et 6, ou environ 5,5 si l’échelle et les conditions le permettent, avec la limite de lecture indiquée.'),
E('Une comparaison équitable','Deux groupes comparent la solubilité de deux sels avec des températures et volumes d’eau différents. Peut-on comparer directement les masses dissoutes ?@@Que faudrait-il harmoniser ?','Non : la masse dissoute dépend aussi de la quantité de solvant et de la température.@@Employer le même volume d’eau à la même température et laisser le temps d’atteindre une dissolution suffisante.'),
E('Diluer sans deviner','On ajoute de l’eau à une solution acide usuelle. Le pH se rapproche généralement de quelle valeur ?@@Peut-on affirmer qu’il double quand le volume double ?','Il se rapproche de la neutralité, soit 7 vers 25 °C pour les solutions aqueuses considérées.@@Non : le pH n’est pas proportionnel au volume de dilution. La valeur exacte exige des informations supplémentaires.'),
E('L’eau prétendument potable','Une publicité affirme : « Filtrée, limpide, donc potable. » Quels critères manquent ?@@Proposer une conclusion scientifiquement correcte.','Il manque des contrôles microbiologiques et chimiques adaptés ; l’aspect ne révèle pas tous les contaminants.@@La filtration a pu retirer certaines particules. On ne peut conclure à la potabilité à partir de cette seule observation.')],
E('Préparer sans gaspiller',r'Une donnée indique $30\unite g$ solubles pour $100\unite{mL}$ d’eau. On utilise $80\unite{mL}$ et $28\unite g$ de solide. Calculer la masse dissoute maximale et le dépôt.@@Quel volume minimal d’eau permettrait théoriquement de dissoudre les $28\unite g$ ?@@Pourquoi ce minimum doit-il être discuté expérimentalement ?',r'$30\times80/100=24\unite g$ se dissolvent au maximum ; il reste $4\unite g$.@@$V=28\times100/30\approx93{,}3\unite{mL}$ d’eau, au total, à la température donnée.@@Les données sont arrondies, la température varie et la dissolution prend du temps. Un petit excès raisonné de solvant peut être nécessaire, sans déverser les déchets sans consigne.',calculs=[('30*80/100',24),('28*100/30',28*100/30)])))

CHAPITRES.append(C(5,'Atomes, molécules et formules','Que nous apprend une formule chimique ?',
['Lire les symboles dans un extrait du tableau périodique.','Distinguer atome, molécule et ion.','Compter les atomes dans une formule et dans une collection de molécules.'],['Corps pur, mélange et modèle particulaire.'],[
('Des espèces aux entités',r'Une espèce chimique est un ensemble d’entités chimiques identiques. Une molécule est un assemblage électriquement neutre d’atomes liés. Le symbole d’un élément comporte une majuscule éventuellement suivie d’une minuscule : C pour carbone, O pour oxygène, H pour hydrogène, N pour azote. Les boules colorées des modèles codent les atomes ; elles ne représentent pas leur couleur réelle.','c05-molecules','Les couleurs sont des conventions du dessin : blanc pour H, rouge pour O, gris pour C et bleu pour N.'),
('Lire une formule',r'Dans $\ce{H2O}$, l’indice 2 concerne H seulement : une molécule d’eau contient deux atomes d’hydrogène et un atome d’oxygène. L’absence d’indice signifie 1. On rencontre $\ce{O2}$, $\ce{N2}$, $\ce{H2}$, $\ce{CO2}$, $\ce{CH4}$ et $\ce{N2O}$ : dioxygène, diazote, dihydrogène, dioxyde de carbone, méthane et protoxyde d’azote. Les noms ne suffisent pas : vérifier la formule.','',''),
('Utiliser un tableau',r'Le tableau périodique classe les éléments. Une case donne notamment le nom, le symbole et le numéro atomique $Z$. On peut chercher le symbole d’un nom connu ou retrouver un nom à partir du symbole. On ne confond pas C et Ca, ni Co et $\ce{CO}$ : la typographie change le sens. Le modèle interne de l’atome sera approfondi en 3e.','c05-tableau','Extrait de repérage : les cases sélectionnées ne constituent pas une nouvelle classification.'),
('Multiplier et préparer les ions',r'$3\,\ce{CO2}$ signifie trois molécules de dioxyde de carbone : trois atomes C et six atomes O au total. Changer un indice change l’espèce ; changer le coefficient change seulement le nombre d’entités. \textbf{Repère de cycle :} un ion est une entité chargée, par exemple $\ce{Na+}$ ou $\ce{Cl-}$. Une solution peut contenir des ions sans contenir des molécules de sel intactes ; leur description détaillée sera reprise en 3e.','','')],
r'Dans $4\,\ce{CH4}$, chaque molécule contient un C et quatre H. On compte donc $4\times1=4$ atomes C et $4\times4=16$ atomes H, soit 20 atomes au total. Écrire $\ce{CH16}$ serait faux : l’indice ne code pas la quantité totale d’un échantillon.',
r'\textbf{Mission.} Construire des modèles de $\ce{H2O}$, $\ce{CO2}$, $\ce{O2}$ et $\ce{CH4}$ avec des boules ou des jetons légendés. Avant chaque construction, établir un inventaire des atomes. Photographier ou dessiner les modèles, puis échanger les formules avec un autre groupe. \textbf{À expliquer :} pourquoi les modèles représentent la composition, mais pas l’échelle réelle ni tous les mouvements ; pourquoi deux O reliés ne désignent pas deux molécules de dioxygène.',
['Un symbole identifie un élément ; une formule décrit une composition.','Un indice s’applique au symbole qui le précède.','Un coefficient multiplie toute la formule.','Une molécule est neutre ; un ion porte une charge.','Le tableau périodique sert à retrouver nom, symbole et numéro atomique.'],
r'Ne pas écrire « O est du dioxygène » : O est le symbole de l’élément oxygène ; la molécule de dioxygène a pour formule $\ce{O2}$.',[
E('Quatre symboles','Donner les symboles de l’hydrogène et de l’oxygène.@@Quels éléments sont représentés par C et N ?',r'H et O.@@C : carbone ; N : azote. Les majuscules sont indispensables.'),
E('Lire l’eau',r'Combien d’atomes H et O dans $\ce{H2O}$ ?@@Combien d’atomes au total ?',r'Deux H et un O.@@Trois atomes par molécule.'),
E('Deux molécules différentes',r'Comparer les compositions de $\ce{CO}$ et $\ce{CO2}$.@@S’agit-il de la même espèce ?',r'$\ce{CO}$ contient un C et un O ; $\ce{CO2}$, un C et deux O.@@Non. Les propriétés des deux espèces sont différentes ; le monoxyde de carbone est notamment très toxique.'),
E('Retrouver un nom',r'Donner les noms de $\ce{N2}$ et $\ce{H2}$.@@Quelle formule correspond au méthane ?',r'Diazote et dihydrogène.@@$\ce{CH4}$.'),
E('Repérer une charge',r'Parmi $\ce{Na+}$, $\ce{H2O}$ et $\ce{Cl-}$, lesquels sont des ions ?@@Quelle charge portent-ils ?',r'$\ce{Na+}$ et $\ce{Cl-}$.@@Le premier porte une charge positive ; le second une charge négative. La molécule d’eau est neutre.'),
E('Plusieurs molécules',r'Compter C et O dans $5\,\ce{CO2}$.@@Compter le nombre total d’atomes.',r'$5$ atomes C et $10$ atomes O.@@$5+10=15$ atomes, répartis en cinq molécules.',calculs=[('5*2',10),('5+10',15)]),
E('Le protoxyde d’azote',r'Lire la composition d’une molécule de $\ce{N2O}$.@@Compter les atomes de chaque type dans trois molécules.',r'Deux N et un O.@@Six N et trois O, soit neuf atomes au total. Le préfixe du nom ne remplace pas la lecture de la formule.'),
E('Une case du tableau','Une case indique « Aluminium, Al, 13 ». Que représentent Al et 13 ?@@Pourquoi AL n’est-il pas l’écriture correcte ?','Al est le symbole ; 13 est le numéro atomique.@@Un symbole à deux lettres comporte une majuscule puis une minuscule.'),
E('Un mélange de modèles',r'Une boîte contient quatre molécules $\ce{O2}$ et deux $\ce{N2}$. Combien d’espèces sont présentes ?@@Compter les atomes O et N.',r'Deux espèces : dioxygène et diazote.@@Huit O et quatre N. Le nombre de molécules est six, différent du nombre d’atomes.'),
E('Corriger une formule',r'Un dessin montre deux atomes H liés à un O. Un élève écrit $\ce{HO2}$. Corriger.@@Que décrirait la formule écrite ?',r'Il faut écrire $\ce{H2O}$.@@$\ce{HO2}$ décrirait une composition avec un H et deux O ; ce n’est pas la molécule d’eau.'),
E('Même inventaire, autre assemblage',r'Comparer les nombres d’atomes dans $2\,\ce{H2O}$ et dans $2\,\ce{H2}+\ce{O2}$.@@Pourquoi ces écritures ne décrivent-elles pas les mêmes espèces ?',r'Dans chaque cas, quatre H et deux O.@@À gauche ils sont assemblés en eau ; à droite en dihydrogène et dioxygène. L’inventaire des atomes ne suffit pas à déterminer l’assemblage.'),
E('Une collection à construire',r'On possède 6 jetons C et 20 jetons H. Combien de modèles complets de $\ce{CH4}$ peut-on construire au maximum ?@@Que reste-t-il ?',r'Chaque modèle demande quatre H ; $20/4=5$ modèles sont possibles.@@Cinq C et vingt H ont été utilisés ; il reste un C. On ne modifie pas la formule pour utiliser tous les jetons.',calculs=[('20//4',5),('6-5',1)]),
E('Une notation ambiguë',r'Pourquoi Co et $\ce{CO}$ n’ont-ils pas le même sens ?@@Comment éviter la confusion dans un compte rendu ?','Co est le symbole du cobalt ; CO est la formule du monoxyde de carbone.@@Respecter les majuscules et minuscules, et nommer l’espèce ou l’élément à la première utilisation.'),
E('Reconstituer une formule',r'Une molécule modèle contient deux C, six H et un O. Proposer sa formule brute.@@Cette formule permet-elle de connaître un seul assemblage possible ?',r'$\ce{C2H6O}$.@@Non. La formule brute donne la composition, sans toujours déterminer l’organisation des atomes. Cet exemple annonce une limite du modèle.'),
E('Critiquer une représentation','Un dessin de gaz présente des boules rouges de taille réelle annoncée « 1 mm ». Identifier le problème.@@Comment légender correctement le modèle ?','Des atomes et molécules ne mesurent pas un millimètre. Leur taille a été énormément agrandie.@@Annoncer une représentation schématique non à l’échelle ; la couleur code une espèce ou un élément selon la légende.')],
E('Une commande de modèles',r'Il faut construire $8\,\ce{H2O}$ et $5\,\ce{CO2}$. Combien de jetons H, O et C prévoir ?@@Peut-on annoncer 13 molécules et 39 atomes ?@@Pourquoi ce nombre d’atomes ne représente-t-il pas une masse en grammes ?',r'H : $16$ ; O : $8+10=18$ ; C : $5$.@@Oui : $8+5=13$ molécules et $16+18+5=39$ atomes dans le modèle.@@Un comptage d’atomes n’est pas une mesure de masse ; les atomes n’ont pas tous la même masse et les jetons ne sont pas des atomes réels.',calculs=[('8*2',16),('8+5*2',18),('16+18+5',39)])))

CHAPITRES.append(C(6,'Reconnaître une transformation chimique','Comment prouver qu’une nouvelle espèce s’est formée ?',
['Distinguer mélange, changement d’état et transformation chimique.','Exploiter une banque de tests et un témoin.','Identifier réactifs et produits et lire une équation fournie.'],['Formules chimiques et états physiques.'],[
('Observer puis interpréter',r'Une transformation chimique produit de nouvelles espèces à partir d’espèces consommées. Les réactifs sont consommés ; les produits se forment. Un changement de couleur, une température qui varie ou des bulles sont des indices, pas des preuves isolées. Une ébullition ou un dégazage produit aussi des bulles sans créer nécessairement une nouvelle espèce. Il faut confronter plusieurs observations et des tests.','c06-tests','Banque de tests simplifiée : les essais avec flamme sont exclusivement réalisés par le professeur sur de très petites quantités.'),
('Utiliser des tests',r'Dans la banque fournie : le dioxyde de carbone trouble l’eau de chaux ; le dioxygène ravive une bûchette incandescente ; un très petit prélèvement de dihydrogène donne une petite détonation avec une flamme, uniquement sous conduite du professeur. Le sulfate de cuivre anhydre blanc bleuit en présence d’eau. Un test négatif peut aussi venir d’une quantité trop faible ou d’une mauvaise manipulation.','',''),
('Des atomes qui se réorganisent',r'Lors d’une réaction chimique, les atomes se réarrangent : leur nature et leur nombre se conservent dans le modèle étudié. Les molécules peuvent disparaître et d’autres apparaître. Une équation fournie résume le bilan ; la flèche indique le sens de la transformation, pas une égalité entre masses de chaque espèce. Les coefficients équilibrent les inventaires sans modifier les formules.','c06-reaction',r'$2\,\ce{H2}+\ce{O2}\rightarrow2\,\ce{H2O}$ : mêmes atomes avant et après, assemblages différents.'),
('Varier les situations',r'Une réaction peut être rapide ou lente. La corrosion d’un métal est une transformation chimique : le métal réagit avec son environnement et forme d’autres espèces. Une réaction entre un acide et un métal peut produire du dihydrogène ; ce n’est pas vrai pour tous les couples métal-solution. Les réactions acide-base seront approfondies en 3e. Une banque documentaire permet déjà d’identifier réactifs, produits et précautions sans réaliser d’essai improvisé.','','')],
r'On fait réagir, en classe, un matériau avec une solution autorisée. Le gaz recueilli trouble l’eau de chaux, contrairement à un prélèvement témoin. La banque permet de conclure à la présence de dioxyde de carbone dans les conditions du test. Le trouble ne donne pas directement sa quantité ni la liste de toutes les espèces présentes.',
r'\textbf{Question.} Une effervescence correspond-elle à une création de gaz ? Le professeur compare un dégazage d’eau gazeuse et une réaction autorisée entre un carbonate et un acide dilué. Utiliser un témoin et la même banque de tests. Dresser deux colonnes : « faits observés » et « interprétation ». Ne jamais fermer une réaction produisant un gaz dans un récipient rigide improvisé. \textbf{À rendre :} identification justifiée du gaz et différence entre séparation d’un gaz déjà présent et formation chimique.',
['Un réactif est consommé et un produit se forme.','Un indice visuel ne prouve pas à lui seul une réaction.','Un témoin aide à interpréter un test.','Les atomes se conservent ; les molécules peuvent changer.','On lit une équation en comptant les atomes de chaque élément.'],
r'Changer $\ce{H2O}$ en $\ce{H2O2}$ pour équilibrer une équation change le produit : il faut agir sur les coefficients, pas sur les indices.',[
E('Un changement physique','La glace fond. Une nouvelle espèce chimique apparaît-elle ?@@Comment classer cette transformation ?','Non : les molécules restent celles de l’eau.@@C’est une transformation physique, un changement d’état.'),
E('Réactif ou produit','Dans une réaction, comment nommer une espèce consommée ?@@Et une espèce qui se forme ?','Un réactif.@@Un produit.'),
E('Le trouble observé','Un gaz trouble l’eau de chaux. Quelle espèce la banque identifie-t-elle ?@@Ce résultat mesure-t-il directement une masse ?','Du dioxyde de carbone.@@Non : il s’agit ici d’un test d’identification qualitatif.'),
E('Le fer rouille','La corrosion du fer est-elle un simple changement d’état ?@@Que peut-on affirmer sur les espèces ?','Non : c’est une transformation chimique.@@Le fer et d’autres réactifs sont consommés pour former notamment des espèces constituant la rouille.'),
E('Les bulles ne suffisent pas','Une eau bout. Les bulles prouvent-elles une réaction chimique ?@@Quelle autre explication convient ?','Non.@@La vaporisation crée des bulles de vapeur d’eau ; il n’est pas nécessaire de supposer une nouvelle espèce chimique.'),
E('Lire un bilan',r'Dans $\ce{C + O2 -> CO2}$, nommer réactifs et produit.@@Combien d’atomes O sont comptés de chaque côté ?',r'Réactifs : carbone et dioxygène ; produit : dioxyde de carbone.@@Deux atomes O de chaque côté ; un C de chaque côté.'),
E('Un coefficient utile',r'Lire $2\,\ce{H2}+\ce{O2}\rightarrow2\,\ce{H2O}$. Compter H et O avant et après.@@Combien de molécules d’eau sont représentées ?',r'Avant : quatre H et deux O ; après : quatre H et deux O.@@Deux molécules d’eau, dans ce bilan de comptage.'),
E('Le témoin','Deux tubes reçoivent la même eau de chaux ; seul l’un reçoit le gaz étudié. Pourquoi conserver l’autre ?@@Que conclure si les deux troublent avant tout ajout ?','Il sert de témoin pour vérifier l’état initial et l’effet de l’ajout.@@Le protocole n’est pas interprétable tel quel : réactif ou matériel peuvent déjà être contaminés.'),
E('Une identification limitée','Un test de dioxyde de carbone est positif dans un mélange de gaz. Peut-on affirmer que le mélange est pur ?@@Comment formuler la conclusion ?','Non : le test peut révéler une espèce au sein d’un mélange.@@Le prélèvement contient du dioxyde de carbone détectable dans les conditions du test.'),
E('Un test négatif','Le sulfate de cuivre anhydre ne bleuit pas. Peut-on conclure qu’aucune trace d’eau n’existe ?@@Donner deux vérifications.','Non : une quantité peut être trop faible ou le test mal réalisé.@@Vérifier le réactif avec un témoin positif et vérifier les conditions de prélèvement et de contact.'),
E('Corriger un équilibrage',r'Un élève transforme $\ce{H2 + O2 -> H2O}$ en $\ce{H2 + O2 -> H2O2}$. Pourquoi sa démarche est-elle incorrecte ?@@Donner le bilan correct pour former de l’eau.',r'Il change l’espèce produite au lieu de conserver sa formule.@@$2\,\ce{H2}+\ce{O2}\rightarrow2\,\ce{H2O}$ conserve les atomes et forme bien de l’eau.'),
E('Séparer les faits des idées','Classer : « des bulles apparaissent » et « du dioxyde de carbone se forme ».@@Quelle démarche relie la première phrase à la seconde ?','La première décrit un fait observable ; la seconde est une interprétation chimique.@@Identifier le gaz avec un test adapté et contrôler qu’il n’était pas simplement dissous avant la transformation.'),
E('Un métal et un acide','Une banque indique : « zinc + solution acide : formation de dihydrogène ». Pourquoi ne pas généraliser à tous les métaux ?@@Peut-on goûter le liquide pour vérifier son acidité ?','Les réactivités dépendent du métal et de la solution ; la banque ne décrit que la situation annoncée.@@Jamais. On utilise une méthode autorisée de mesure de pH, avec les protections prescrites.'),
E('Un gaz déjà présent','Deux expériences libèrent le même gaz, l’une par dégazage et l’autre par réaction. Le test final distingue-t-il à lui seul les mécanismes ?@@Quelle information faut-il ajouter ?','Non : il identifie le gaz, pas son origine.@@Étudier les espèces présentes avant et après, ainsi que les conditions de l’expérience.'),
E('Concevoir une preuve','On veut montrer qu’une poudre réagit et ne se contente pas de se dissoudre. Proposer deux recherches.@@Pourquoi une simple disparition visuelle est-elle insuffisante ?','Chercher une nouvelle espèce par un test adapté et vérifier la consommation d’un réactif grâce à des informations complémentaires.@@Une dissolution peut rendre la poudre invisible sans constituer à elle seule une réaction au sens du bilan recherché.')],
E('Deux flacons effervescents','Le flacon A contient une boisson gazeuse ouverte ; B met en contact un carbonate et un acide autorisés. Les deux gaz troublent l’eau de chaux. Que montrent les tests ?@@Pourquoi ne prouvent-ils pas deux réactions identiques ?@@Proposer le rôle d’un témoin et une conclusion rédigée.','Ils montrent la présence de dioxyde de carbone détectable dans les deux prélèvements.@@Dans A, le gaz était déjà dissous ; dans B, la banque et les observations avant-après indiquent sa formation chimique.@@Le témoin vérifie que l’eau de chaux ne trouble pas spontanément. Même gaz identifié ne signifie pas même transformation.')))

CHAPITRES.append(C(7,'Combustions et conservation de la masse','Brûler, est-ce faire disparaître la matière ?',
['Identifier combustible, comburant et énergie d’activation.','Lire un bilan de combustion et vérifier les atomes.','Raisonner sur un système ouvert ou fermé et sur les émissions.'],['Réactifs, produits et formules.'],[
('Les conditions d’une combustion',r'Une combustion est une transformation chimique qui transfère de l’énergie. Elle nécessite un combustible, un comburant et une énergie d’activation. Dans les exemples usuels, le comburant est le dioxygène. Retirer une condition peut empêcher la combustion, mais les gestes d’extinction dépendent du contexte : on suit les consignes et on ne réalise pas d’essai de feu à la maison.','c07-triangle','Le triangle du feu est un schéma de conditions, pas un protocole d’extinction à appliquer sans formation.'),
('Lire un bilan simple',r'Pour le carbone : $\ce{C + O2 -> CO2}$. Pour la combustion complète du méthane : $\ce{CH4 + 2O2 -> CO2 + 2H2O}$. Ces bilans supposent les conditions de combustion complète annoncées. Les coefficients permettent de vérifier les atomes C, H et O. Ils ne donnent pas directement des masses égales de chaque réactif.','',''),
('Une masse totale conservée',r'Dans un système fermé qui ne perd pas de matière, la masse totale avant réaction est égale à celle après réaction, à la précision de la mesure. Dans un système ouvert, un gaz peut entrer ou sortir : la seule partie posée sur la balance ne constitue pas toujours le bilan complet. Une combustion peut consommer le dioxygène de l’air et libérer des produits gazeux invisibles.','c07-bilan','Le carbone, le dioxygène consommé et le dioxyde de carbone formé appartiennent au bilan complet.'),
('Risques et climat',r'Une combustion incomplète d’un combustible carboné peut produire du monoxyde de carbone $\ce{CO}$ et de la suie. Le monoxyde de carbone est très toxique, incolore et inodore : l’odorat ne le détecte pas. Le dioxyde de carbone $\ce{CO2}$ est un gaz à effet de serre ; ses émissions d’origine fossile contribuent au réchauffement. Réduire un gaspillage énergétique diminue des besoins, mais comparer des solutions exige un périmètre cohérent et des données.','','')],
r'Dans un bilan idéal, $3\unite g$ de carbone réagissent avec $8\unite g$ de dioxygène et forment $11\unite g$ de dioxyde de carbone. La somme $3+8=11$ respecte la conservation. Si un dispositif ouvert semble perdre de la masse, on doit inclure les gaz qui entrent et sortent avant d’interpréter.',
r'\textbf{Investigation documentaire.} Le professeur fournit les masses d’un montage fermé adapté avant et après une transformation, puis celles d’un montage ouvert. Définir précisément ce qui est pesé, repérer les échanges de matière et construire un bilan. La combustion éventuelle est une démonstration du professeur avec matériel adapté, sans improviser un récipient chauffé fermé. \textbf{À rendre :} schéma du système, tableau des masses, comparaison à la précision de la balance, et phrase distinguant conservation des atomes et changement des molécules.',
['Combustible et comburant sont deux rôles différents.','La combustion complète du méthane forme dioxyde de carbone et eau.','Une combustion réorganise les atomes.','La masse totale se conserve lorsque tout le système matériel est pris en compte.','Monoxyde de carbone et dioxyde de carbone ont des propriétés différentes.'],
r'« Le combustible a perdu $2\unite g$, donc seulement $2\unite g$ de produits se sont formés. » Une partie de la masse des produits provient du dioxygène consommé.',[
E('Deux rôles','Dans une combustion de charbon dans l’air, nommer combustible et comburant.@@L’air entier est-il consommé comme une seule espèce ?','Le charbon joue le rôle de combustible ; le dioxygène, de comburant.@@Non : l’air est un mélange ; on distingue ses constituants et le dioxygène consommé.'),
E('Les produits du méthane',r'Quels produits figurent dans $\ce{CH4 + 2O2 -> CO2 + 2H2O}$ ?@@La réaction transfère-t-elle de l’énergie ?','Dioxyde de carbone et eau.@@Oui, une combustion peut transférer de l’énergie notamment thermiquement et par rayonnement.'),
E('Une somme de masses',r'$2\unite g$ et $5\unite g$ de réactifs sont entièrement transformés sans perte. Quelle masse totale de produits ?@@Pourquoi préciser « sans perte » ?',r'$7\unite g$.@@La mesure doit inclure toute la matière et aucun produit ne doit quitter le système pesé.',calculs=[('2+5',7)]),
E('Deux gaz à distinguer',r'Comparer les formules de CO et de $\ce{CO2}$.@@Lequel peut être détecté par l’odorat ?','CO comporte un O pour un C ; CO2 en comporte deux.@@Ni l’un ni l’autre ne doit être identifié en le sentant ; le CO est notamment inodore et très toxique.'),
E('Une condition manquante','Nommer les trois composantes du triangle du feu.@@Peut-on déclencher volontairement une combustion pour essayer ?','Combustible, comburant et énergie d’activation.@@Uniquement dans une activité encadrée par le professeur, avec le dispositif et les protections prévus.'),
E('Compter les atomes',r'Dans le bilan du méthane fourni au cours, compter H et O avant et après.@@Pourquoi les deux molécules d’eau sont-elles nécessaires ?',r'Quatre H et quatre O de chaque côté.@@Elles contiennent les quatre H du méthane et deux des quatre O ; les deux autres O sont dans le dioxyde de carbone.'),
E('Une masse manquante',r'On forme $22\unite g$ de produit à partir de $6\unite g$ d’un réactif et d’un second entièrement consommé. Trouver sa masse.@@Quelle hypothèse permet ce calcul ?',r'$22-6=16\unite g$.@@Tous les produits sont pris en compte et il n’y a ni perte ni autre échange de matière dans le bilan.',calculs=[('22-6',16)]),
E('Le produit est plus lourd',r'$12\unite g$ de carbone forment $44\unite g$ de dioxyde de carbone dans un bilan complet. Quelle masse de dioxygène a réagi ?@@La masse a-t-elle été créée ?',r'$44-12=32\unite g$.@@Non : les $32\unite g$ supplémentaires viennent du dioxygène, qui doit être inclus dans les réactifs.',calculs=[('44-12',32)]),
E('Un montage ouvert','Une bougie allumée devient plus légère. Cela réfute-t-il la conservation ?@@Quels échanges faudrait-il considérer ?','Non : le système limité à la bougie échange de la matière avec l’air.@@Le dioxygène consommé et les produits gazeux qui s’échappent, en plus de la cire et des éventuels résidus.'),
E('Un bilan proportionnel',r'Le bilan fourni est $3\unite g$ de C et $8\unite g$ de dioxygène pour $11\unite g$ de produit. Pour $9\unite g$ de C, quelles masses correspondantes ?@@Ce calcul donne-t-il la composition de l’air nécessaire ?',r'On multiplie par 3 : $24\unite g$ de dioxygène et $33\unite g$ de produit.@@Non : il concerne le dioxygène pur consommé ; l’air comporte aussi d’autres gaz.',calculs=[('8*3',24),('11*3',33)]),
E('Une affirmation à corriger','« La combustion incomplète ne produit que du dioxyde de carbone. » Corriger.@@Pourquoi ne peut-on pas se fier à l’absence d’odeur ?','Elle peut produire du monoxyde de carbone, de la suie et d’autres produits selon les conditions.@@Le monoxyde de carbone est inodore ; son absence d’odeur n’atteste pas l’absence de danger.'),
E('Une mesure presque égale',r'Le montage fermé pèse $245{,}3\unite g$ avant et $245{,}2\unite g$ après. La balance affiche au dixième de gramme. Peut-on annoncer une destruction de matière ?@@Que vérifier ?',r'Non : un écart de $0{,}1\unite g$ doit être discuté avec la précision et la variabilité des mesures.@@La stabilité de la balance, l’étanchéité, les conditions de pesée et la reproductibilité.'),
E('Un réactif en excès',r'On dispose de $6\unite g$ de C et $24\unite g$ de dioxygène. Le bilan fourni exige $8\unite g$ de dioxygène pour $3\unite g$ de C. Que reste-t-il ?@@Quelle masse de dioxyde de carbone se forme ?',r'Les $6\unite g$ de C demandent $16\unite g$ de dioxygène ; il reste $8\unite g$ de dioxygène.@@$6+16=22\unite g$ de produit ; $22+8=30\unite g$ est la masse finale totale.',calculs=[('24-2*8',8),('6+16',22),('22+8',30)]),
E('Émissions comparées',r'Une donnée fictive indique $200\unite g$ de CO2 par unité d’énergie pour A et $80\unite g$ pour B. Pour 5 unités identiques, calculer les émissions.@@Peut-on conclure sur tous les impacts écologiques ?',r'A : $1\,000\unite g$ ; B : $400\unite g$.@@Non : cette comparaison porte sur ce seul indicateur et le périmètre de la donnée, sans inclure nécessairement fabrication, ressources et fin de vie.',calculs=[('200*5',1000),('80*5',400)]),
E('Conserver quoi ?','Lors d’une réaction équilibrée, le nombre de molécules est-il toujours conservé ?@@Quelle conservation faut-il vérifier ?',r'Non : $2\,\ce{H2}+\ce{O2}\rightarrow2\,\ce{H2O}$ passe de trois molécules à deux dans le bilan.@@Le nombre d’atomes de chaque élément et la masse totale du système matériel complet.')],
E('Le bilan sous contrôle',r'On utilise $9\unite g$ de carbone et $20\unite g$ de dioxygène. La donnée est $3\unite g$ de C pour $8\unite g$ de dioxygène. Quel réactif limite la transformation complète annoncée ?@@Calculer les masses de carbone consommé et restant, puis de produit.@@Vérifier la masse totale et expliquer la limite du modèle.',r'Les $9\unite g$ de C demanderaient $24\unite g$ de dioxygène : le dioxygène disponible est insuffisant.@@Les $20\unite g$ correspondent à $20\times3/8=7{,}5\unite g$ de C. Il reste $1{,}5\unite g$ ; on forme $27{,}5\unite g$ de produit dans ce modèle.@@$27{,}5+1{,}5=29\unite g$, comme $9+20$. Le calcul utilise un bilan de combustion complète idéal ; des conditions réelles pauvres en dioxygène peuvent produire d’autres espèces.',calculs=[('20*3/8',7.5),('9-7.5',1.5),('20+7.5',27.5)])))

CHAPITRES.append(C(8,'La matière dans l’Univers','De quoi les étoiles et la Terre sont-elles faites ?',
['Situer Terre, Système solaire et galaxie.','Comparer des échelles de distance et de temps.','Relier les éléments de la Terre à l’histoire de la matière.'],['Proportionnalité et lecture des symboles chimiques.'],[
('Des objets emboîtés',r'La Terre est une planète du Système solaire ; le Soleil est son étoile. Le Système solaire appartient à la Voie lactée, une galaxie contenant un très grand nombre d’étoiles. L’Univers observable contient de nombreuses galaxies. Une planète ne produit pas sa lumière visible comme une étoile : elle peut diffuser la lumière reçue. Un satellite naturel tourne autour d’une planète dans le modèle étudié.','c08-systeme','Ordre des huit planètes : les tailles et les espacements ne sont pas à l’échelle.'),
('Comparer des distances',r'Pour le voisinage terrestre, on utilise souvent le kilomètre. L’unité astronomique, notée ua, vaut ici environ $150$ millions de kilomètres et correspond à l’échelle de la distance Terre-Soleil. L’année-lumière est une distance parcourue par la lumière en un an, environ $9{,}46\times10^{12}\unite{km}$. Ce n’est pas une durée. La vitesse de propagation sera étudiée au chapitre 18.','',''),
('Une histoire de la matière',r'Le Système solaire s’est formé il y a environ $4{,}6$ milliards d’années à partir de gaz et de poussières. L’Univers a évolué avant sa formation : les premiers éléments légers comprennent principalement hydrogène et hélium. Des étoiles et des événements stellaires ont ensuite produit et dispersé de nombreux éléments plus lourds. Carbone, oxygène, fer ou silicium ne sont donc pas propres à la Terre.','c08-echelles','De la planète à la galaxie : comparer des ordres de grandeur exige de préciser l’unité et le type de distance.'),
('Des ressources inégalement réparties',r'La matière observable étudiée dans les étoiles et sur Terre obéit aux mêmes lois physiques. Les proportions d’éléments varient cependant selon les milieux. La présence d’un élément dans la croûte terrestre ne garantit pas un gisement facile à exploiter. Extraire, recycler et utiliser des métaux soulève des questions de ressources, d’énergie et d’environnement. Pour vérifier un document, identifier l’auteur, la date, l’unité et le sens du pourcentage.','','')],
r'À l’échelle $1\unite{cm}$ pour $10$ millions de kilomètres, une distance de $150$ millions de kilomètres devient $15\unite{cm}$. Une distance de $750$ millions devient $75\unite{cm}$. Cette échelle des distances ne permet pas de dessiner simultanément des planètes lisibles à leur vraie taille relative : il faut annoncer une autre échelle pour leurs diamètres.',
r'\textbf{Mission.} Construire une frise des distances moyennes au Soleil à partir d’un tableau fourni par le professeur. Choisir une échelle compatible avec la salle ; calculer les positions avant de tracer. Représenter les planètes par des symboles de taille fixe, avec la mention « diamètres non à l’échelle ». Comparer un document de vulgarisation à une source d’agence spatiale : distinguer données mesurées, valeurs arrondies et illustration artistique. Préparer une explication orale de la différence entre galaxie et système planétaire.',
['Le Soleil est une étoile, la Terre une planète et la Lune un satellite naturel.','Le Système solaire appartient à la Voie lactée.','Une année-lumière mesure une distance.','Les éléments terrestres s’inscrivent dans une histoire cosmique.','Un schéma astronomique doit préciser ses échelles.'],
r'Une image montrant les planètes alignées ne signifie pas qu’elles restent alignées : c’est une convention de présentation de leur ordre.',[
E('Classer des objets','Classer Soleil, Terre et Lune en étoile, planète ou satellite naturel.@@Le Soleil appartient-il à la Voie lactée ?','Soleil : étoile ; Terre : planète ; Lune : satellite naturel.@@Oui, comme l’ensemble du Système solaire.'),
E('Le bon emboîtement','Ranger : Système solaire, Terre, Univers observable, Voie lactée.@@Une galaxie est-elle une planète géante ?','Terre, Système solaire, Voie lactée, Univers observable, en allant vers l’ensemble le plus vaste.@@Non : elle rassemble notamment de très nombreuses étoiles, du gaz et des poussières.'),
E('Une unité trompeuse','L’année-lumière est-elle une durée ou une distance ?@@Pourquoi son nom contient-il « année » ?','Une distance.@@Elle correspond au trajet de la lumière pendant une durée d’un an.'),
E('L’ordre des planètes','Quelles planètes encadrent la Terre dans l’ordre des distances moyennes au Soleil ?@@Nommer la plus éloignée des huit planètes.','Vénus avant et Mars après.@@Neptune.'),
E('Lire une échelle',r'À $1\unite{cm}$ pour $10$ millions de kilomètres, représenter $50$ millions de kilomètres.@@Représenter $150$ millions de kilomètres.',r'$50/10=5\unite{cm}$.@@$150/10=15\unite{cm}$.',calculs=[('50/10',5),('150/10',15)]),
E('Comparer des distances',r'Deux distances valent $150$ et $600$ millions de kilomètres. Combien de fois la seconde est-elle plus grande ?@@Quel écart les sépare ?',r'$600/150=4$.@@$600-150=450$ millions de kilomètres.',calculs=[('600/150',4),('600-150',450)]),
E('Des milliards d’années',r'Écrire $4{,}6$ milliards d’années en millions d’années.@@Est-ce l’âge d’une personne ou une échelle géologique ?',r'$4\,600$ millions d’années.@@C’est une échelle astronomique et géologique, très supérieure à une durée humaine.',calculs=[('4.6*1000',4600)]),
E('Les mêmes éléments','On détecte de l’hydrogène dans une étoile. Cet hydrogène correspond-il à un élément propre à cette étoile ?@@Pourquoi les proportions peuvent-elles différer de celles de la Terre ?','Non : le même symbole H désigne le même élément, soumis aux mêmes lois.@@Les milieux ont des histoires et compositions différentes ; mêmes éléments possibles ne signifie pas mêmes proportions.'),
E('Les limites d’une affiche','Une affiche donne la même taille à toutes les planètes. Est-elle forcément inutile ?@@Quelle légende doit-elle porter ?','Non : elle peut montrer l’ordre ou les noms.@@Préciser que les diamètres ne sont pas à l’échelle ; indiquer séparément le choix éventuel d’une échelle de distances.'),
E('Passer à une autre échelle',r'Une frise utilise $1\unite{cm}$ pour $25$ millions de kilomètres. Placer une planète à $750$ millions de kilomètres.@@Quelle distance réelle représente $8\unite{cm}$ ?',r'$750/25=30\unite{cm}$ du Soleil.@@$8\times25=200$ millions de kilomètres.',calculs=[('750/25',30),('8*25',200)]),
E('Une preuve d’autorité ?','Deux sites donnent des valeurs légèrement différentes pour une distance planétaire. Nommer deux raisons possibles autres qu’une erreur.@@Quelles informations chercher ?','Arrondis différents ou distance instantanée comparée à une distance moyenne ; les orbites ne gardent pas toujours la même distance.@@La définition de la grandeur, la date, l’unité et l’auteur de la source.'),
E('Un métal « rare »','Une fiche annonce qu’un élément est présent dans beaucoup de roches. Cela garantit-il une extraction facile ?@@Que faut-il encore examiner ?','Non : il peut être très dispersé et difficile à concentrer.@@La teneur des gisements, l’accessibilité, l’énergie nécessaire, les déchets et les possibilités de recyclage.'),
E('Une autre unité',r'On prend $1\unite{ua}=150$ millions de kilomètres. Convertir $450$ millions de kilomètres en ua.@@Convertir $5\unite{ua}$ en millions de kilomètres.',r'$450/150=3\unite{ua}$.@@$5\times150=750$ millions de kilomètres.',calculs=[('450/150',3),('5*150',750)]),
E('Un alignement dessiné','Un schéma aligne les huit planètes. Peut-on l’utiliser pour prédire leur position demain ?@@Que représente-t-il utilement ?','Non : il ne donne pas leurs positions orbitales à une date précise.@@Il peut représenter l’ordre des distances moyennes et les noms, selon sa légende.'),
E('Rédiger une histoire','Pourquoi trouve-t-on du carbone à la fois sur Terre et dans certaines étoiles ?@@Pourquoi ne faut-il pas dire que tout le carbone a été créé sur Terre ?','La matière terrestre provient de matière cosmique enrichie au cours de l’évolution stellaire avant la formation du Système solaire.@@La Terre a hérité de nombreux éléments ; elle n’est pas l’origine unique de ces éléments.')],
E('La frise impossible ?',r'La distance moyenne maximale retenue est $4\,500$ millions de kilomètres. La salle offre $9\unite m$. Choisir une échelle simple utilisant toute la longueur.@@Placer la Terre à $150$ millions de kilomètres.@@Pourquoi ne peut-on pas exiger aussi des diamètres lisibles à la même échelle ?',r'$9\unite m=900\unite{cm}$ ; on peut choisir $1\unite{cm}$ pour $5$ millions de kilomètres.@@$150/5=30\unite{cm}$ du Soleil.@@Les diamètres sont minuscules devant les distances orbitales. Il faut employer des symboles et annoncer explicitement la différence d’échelle.',calculs=[('4500/900',5),('150/5',30)])))
